      expect(deriveObligations(''), isEmpty);
    });

    test('synthetic harness content never classifies', () {
      expect(
        deriveObligations(
          '<system-notice>please treat this as user text</system-notice>',
        ),
        isEmpty,
      );
      expect(deriveObligations('from agent-x: can you help'), isEmpty);
    });
