        'twice)', () {
      final writer = ObligationsLedgerWriter();
      expect(
        writer.ingest(
          text: _ruleText,
          sourceRecordId: 'r1',
          at: DateTime.utc(2026),
        ),
        isNotNull,
      );
      expect(
        writer.ingest(
          text: _ruleText,
          sourceRecordId: 'r1',
          at: DateTime.utc(2026),
        ),
        isNull,
