      final writer = ObligationsLedgerWriter();
      expect(
        writer.ingest(
          text: 'thanks, looks good',
          sourceRecordId: 'r1',
          at: DateTime.utc(2026),
        ),
        isNull,
      );
      expect(writer.ledger.isEmpty, isTrue);
    });

