/// Returns the appended record, or `null` when there is nothing to compact.
/// Failure-safe: when summarization throws, no record is appended and the
/// session history is fully preserved. The session's
/// [Session.buildContextMessages] then projects the summary in place of the
/// compacted region.
Future<CompactionRecord?> compactSession(
  Session session, {
  String? customInstructions,
  CancelToken? cancelToken,
}) async {
  final path = await session.getBranch();
  final tokensBefore = estimateContextTokens(
    await session.buildContextMessages(),
  ).tokens;
  final preparation = prepareCompaction(path, tokensBefore: tokensBefore);
  if (preparation == null) return null;
  final result = await compact(
    preparation,
    customInstructions: customInstructions,
    cancelToken: cancelToken,
  );
  final recordId = await session.appendCompaction(
    summary: result.summary,
    firstKeptEntryId: result.firstKeptEntryId,
    tokensBefore: result.tokensBefore,
    details: result.details,
    record is BranchSummaryRecord ||
    record is CompactCheckpointRecord;

/// Rebuilds `state.messages` from the session projection, zeroing usage
/// anchors on rebuilt transcripts (the classic engine's convention —
/// rebuilt messages carry no trustworthy usage).
Future<int> _refreshState() async {
  final rebuilt = await session.buildContextMessages();
  state.messages = [
    for (final message in rebuilt)
      message is AssistantMessage
          ? message.copyWith(usage: Usage.zero)
          : message,
  ];
  return _requestTokens();
}
  // messages carry generation-time usage from BEFORE the compaction —
  // anchoring the estimator at it would keep reporting the
  // pre-compaction size and retrigger the loop forever. Clear it; the
  // next turn's usage report re-anchors the estimate.
  state.messages = [
    for (final message in await session.buildContextMessages())
      if (message is AssistantMessage)
        message.copyWith(usage: Usage.zero)
      else
        message,
  ];

