{"command":"python3 -c "
import json, subprocess
d = json.load(open('outputs/pr_review.json'))
print('JSON OK, recommendation:', d['recommendation'], d['issueCounts'])
for c in d['inlineComments']:
    r = subprocess.run(['git','diff','origin/main...HEAD','--',c['path']], capture_output=True, text=True).stdout
    added = set()
    import re
    newline = 0
    for ln in r.splitlines():
        m = re.match(r'@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@', ln)
        if m:
            newline = int(m.group(1)); continue
        if newline and not ln.startswith('+++') and not ln.startswith('---'):
            if ln.startswith('+'): added.add(newline)
            if ln[0] in ' +': newline += 1
    ok = c['line'] in added
    print(('OK ' if ok else 'MISS ') + c['path'] + ':' + str(c['line']))
""}

