      return [
        'open obligations (close with {"id": "..."}):',
        for (final e in open)
          '- ${e.id} [${e.kind.jsonName}] '
              '${capLedgerText(e.text) ?? ''}',
      ].join('\n');
    }
    final parsed = switch (status) {
      'done' => ObligationStatus.done,
      'superseded' => ObligationStatus.superseded,
      _ => null,
    };
    if (parsed == null) {
